  const footer = (alwaysShowLabels = false) => <div className="mt-auto">{(!collapsed || alwaysShowLabels) && <div className="mb-4 rounded-xl border border-pink-300/20 bg-gradient-to-br from-pink-400/10 to-purple-500/10 p-4"><div className="mb-2 flex items-center gap-2 text-pink-200"><Crown size={14} /><span className="text-[10px] font-bold tracking-widest">UPGRADE TO PRO</span></div><p className="mb-3 text-[10px] leading-relaxed text-white/40">Unlock priority routes, higher limits, and API access.</p><button onClick={() => { navigate("/pricing"); setMobileOpen(false); }} className="btn-pink w-full rounded-md py-2 text-[10px] font-bold tracking-widest">$29.99 / MONTH</button></div>}{!alwaysShowLabels && <button onClick={() => setCollapsed(!collapsed)} className="mx-auto flex h-9 w-full items-center justify-center gap-2 rounded-lg text-white/30 transition hover:bg-white/5 hover:text-cyan-300">{collapsed ? <ChevronRight size={16} /> : <><ChevronLeft size={16} /><span className="text-[9px] tracking-[.15em]">COLLAPSE PANEL</span></>}</button>}{(!collapsed || alwaysShowLabels) && <div className="mt-3 truncate text-center font-mono text-[8px] tracking-[.12em] text-white/20">{userEmail}</div>}<button onClick={onLogout} className={`mt-3 flex w-full items-center justify-center gap-2 rounded-lg border border-red-400/20 bg-red-400/[.05] py-2 text-[9px] font-bold tracking-widest text-red-300 transition hover:bg-red-400/15 ${!alwaysShowLabels && collapsed ? "px-0" : ""}`}><LogOut size={13} />{(!collapsed || alwaysShowLabels) && "LOG OUT"}</button>{(!collapsed || alwaysShowLabels) && <div className="mt-3 text-center text-[9px] text-white/20">Proudly made by Branice <span className="text-red-400">❤️</span></div>}</div>;
  return <><aside className={`fixed bottom-0 left-0 top-0 z-40 hidden flex-col border-r border-cyan-300/10 bg-[#070713]/95 px-3 py-5 backdrop-blur-2xl transition-[width] duration-300 md:flex ${collapsed ? "w-[72px]" : "w-[280px]"}`}>
    <div className={`mb-12 flex items-center ${collapsed ? "justify-center" : "justify-between px-2"}`}><Logo compact={collapsed} />{!collapsed && <div className="font-mono text-[8px] tracking-[.2em] text-white/25">v2.0.6</div>}</div>
    {!collapsed && <div className="mb-4 px-3 font-mono text-[9px] tracking-[.22em] text-white/25">COMMAND CENTER</div>}{links()}{footer()}
  </aside><div className={`fixed inset-0 z-[70] md:hidden ${mobileOpen ? "pointer-events-auto" : "pointer-events-none"}`}><div onClick={() => setMobileOpen(false)} className={`absolute inset-0 bg-black/80 transition-opacity ${mobileOpen ? "opacity-100" : "opacity-0"}`} /><aside className={`absolute bottom-0 left-0 top-0 z-[80] flex w-[300px] flex-col border-r border-cyan-300/10 bg-[#070713] px-3 py-5 shadow-2xl transition-transform duration-300 ${mobileOpen ? "translate-x-0" : "-translate-x-[320px]"}`}><div className="mb-10 flex items-center justify-between px-2"><Logo /><button onClick={() => setMobileOpen(false)} className="rounded-lg p-2 text-white/50 hover:bg-white/5 hover:text-cyan-300"><X size={18} /></button></div><div className="mb-4 px-3 font-mono text-[9px] tracking-[.22em] text-white/25">COMMAND CENTER</div>{links(true)}{footer(true)}</aside></div></>;
