  return <div className="mx-auto max-w-[1400px] fade-up"><PageHeading eyebrow="VERIFICATION LAYER / 04" title="FOREIGN NUMBERS" description="Receive verification codes through trusted virtual numbers. One-time use, clear expiry, zero noise." action={<StatusBadge tone="green">8,410 NUMBERS AVAILABLE</StatusBadge>} /><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{numberCountries.map((n, i) => <button key={n.country} onClick={() => setSelected(n)} className="glass glass-hover rounded-2xl p-5 text-left" style={{ animationDelay: `${i * 40}ms` }}><div className="mb-5 flex items-start justify-between"><span className="text-3xl">{n.flag}</span><span className="font-mono text-[9px] text-lime-300">{n.available} AVAIL.</span></div><h3 className="text-sm font-semibold text-white">{n.country}</h3><div className="mt-2 flex items-end justify-between"><span className="font-mono text-xl text-cyan-300">{n.price}</span><span className="text-[9px] text-white/30">per number</span></div><div className="mt-4 flex items-center gap-1 text-[9px] font-bold tracking-widest text-white/35 transition group-hover:text-cyan-300">SELECT SERVICE <ArrowRight size={12} /></div></button>)}</div><div className="glass mt-6 overflow-hidden rounded-2xl"><div className="border-b border-white/10 px-5 py-4"><h2 className="font-display text-sm tracking-[.14em] text-white">MY NUMBERS</h2><p className="mt-1 text-[10px] text-white/35">Numbers you have provisioned will appear here.</p></div><EmptyTable icon={Smartphone} title="No numbers provisioned" description="Choose a country above to get started." /></div><div className="mt-5 flex items-center gap-2 rounded-xl border border-yellow-300/15 bg-yellow-300/[.04] px-4 py-3 text-[10px] text-yellow-100/55"><CircleHelp size={14} className="text-yellow-300" /> Numbers are for verification only. One-time use. Misuse will result in a ban per our Terms.</div>{selected && <ServiceModal country={selected} close={() => setSelected(null)} buy={openPaywall} />}</div>;
